function validate(input) {
  const [{ Users = [] }] = input;
  const ids = new Set();
  for (const [id, name, mail] of Users) {
    if (id === null) return 'Every user needs a user_id.';
    if (ids.has(id)) return `user_id ${id} appears twice in Users.`;
    ids.add(id);
    if (name !== null && name.length > 30) return `The name of user ${id} is longer than 30 characters.`;
    if (mail !== null && mail.length > 50) return `The mail of user ${id} is longer than 50 characters.`;
  }
  return null;
}

