function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const firsts = ['a', 'b', 'k', 'Z', 'M', 'x', 'Q', '7', '.', '_', '-', '#'];
  const rests = ['a', 'e', 'R', 'o', 'T', '0', '9', '_', '.', '-', 'z', 'L', '#', '+', ' ', '@', '!'];
  const domains = ['@leetcode.com', '@leetcode.com', '@leetcode.com', '@leetcode.com', '@LeetCode.com', '@leetcode.COM', '@gmail.com', '@leetcodeXcom', '@leetcode.com.au', '@leetcode.comm', 'leetcode.com', '@leetcode.co', ''];
  const names = ['Winston', 'Ann', 'Bella', 'Sally', 'Marwan', 'David', 'Kim', 'Ravi'];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const Users = [];
  for (let i = 0; i < count; i++) {
    let prefix = rand() < 0.95 ? pick(firsts) : '';
    const extra = Math.floor(rand() * 6);
    for (let j = 0; j < extra; j++) prefix += rand() < 0.85 ? pick(rests.slice(0, 12)) : pick(rests);
    Users.push([size === 'small' ? i * 3 + 1 : i + 1, pick(names), prefix + pick(domains)]);
  }
  return [{ Users }];
}
